-- Function to check if a message contains any banned word
function containsBannedWord(message, wordList)
    message = message:lower() -- Normalize message for case-insensitive checking
    for _, word in ipairs(wordList) do
        local pattern = "%f[%a]" .. word:lower() .. "%f[%A]" -- Match whole word only
        if message:find(pattern) then
            return true, word
        end
    end
    return false
end

