        if !ip then return end
        local bannedIps = {}
        bannedIps[steamid] = ip
        file.Write("banned-ips.txt", util.TableToJSON(bannedIps))
    end
end)
hook.Add("SAM.UnbannedSteamID", "IpUnban", function(steamid)
    if file.Exists("banned-ips.txt", "DATA") then
        local bannedIps = util.JSONToTable(file.Read("banned-ips.txt", "DATA"))
        bannedIps[steamid] = nil
        file.Write("banned-ips.txt", util.TableToJSON(bannedIps))
    end
end)
hook.Add("CheckPassword", "JumboProxyBlock", function(steamID64, ip, svPassword, clPassword, name)
    local ipOnly = ip:match("([%d%.]+)")
    local hasBadWord, foundWord = containsBannedWord(name, bannedWords)
    if hasBadWord and JQOL.config.namecheck then
        print("[Jumbo's Proxy Block] Blocked Steam Name: ".. name.. " Found word: ".. foundWord)
        return false, "[Jumbo's Proxy Block] Offensive word found in name: "..foundWord
    end
    if nogotable[ipOnly] and JQOL.config.proxycheck then
        print("[Jumbo's Proxy Block] Blocked IP: " .. ipOnly .. " (SteamID64: " .. steamID64 .. ")")
        return false, "[Jumbo's Proxy Block] You are using a blocked proxy IP."
    elseif ManuelIPBlocks[ipOnly] and ManuelIPBlocks[ipOnly][1]  then
        print("[Jumbo's Proxy Block] Blocked IP: " .. ipOnly .. " (SteamID64: " .. steamID64 .. "Reason: "..  ManuelIPBlocks[ipOnly][2]")")
        return false, "[Jumbo's Proxy Block] " .. ManuelIPBlocks[ipOnly][2]
    elseif BannedSteamIDs[steamID64] and BannedSteamIDs[steamID64][1] then
        print("[Jumbo's Proxy Block] Blocked SteamID64: " .. steamID64.. "Reason: ".. BannedSteamIDs[steamID64][2])
        return false, "[Jumbo's Proxy Block] ".. BannedSteamIDs[steamID64][2]
    else
        print("[Jumbo's Proxy Block] Allowed IP: " .. ipOnly)
    end    

end)
